package top.monitorglobal.tv;
import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w1280dp-h720dp-land-hdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class WeatherAiPresentationTest {
 Context c;long now;@Before public void setup(){c=RuntimeEnvironment.getApplication();now=System.currentTimeMillis();c.getSharedPreferences("weather-ai",0).edit().clear().commit();}
 String payload(String kind,long at,long ref,String text)throws Exception{return new JSONObject().put("version","weather-briefing-v1").put("area","liberdade").put("status","ready").put("model",WeatherBriefing.MODEL).put("kind",kind).put("generatedAt",now).put("expiresAt",now+600000).put("dataAt",at).put("referenceAt",ref).put("rainState","soon").put("text",text).toString();}
 String texts(View v){if(v.getVisibility()!=View.VISIBLE)return "";if(v instanceof TextView)return ((TextView)v).getText().toString();String s="";if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s+=texts(((ViewGroup)v).getChildAt(i))+" ";return s;}
 void export(View card,String name)throws Exception{int width=780;card.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1000,View.MeasureSpec.AT_MOST));card.layout(0,0,width,card.getMeasuredHeight());assertTrue(card.getHeight()<850);check(card);Bitmap b=Bitmap.createBitmap(width,card.getHeight(),Bitmap.Config.ARGB_8888);card.draw(new Canvas(b));java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.JPEG,82,out);b.recycle();System.out.println("WEATHER_AI_"+name+" "+java.util.Base64.getEncoder().encodeToString(out.toByteArray()));}
 void check(View v){if(v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView t=(TextView)v;assertNotNull(t.getLayout());assertTrue(t.getText().toString(),t.getLayout().getLineEnd(t.getLayout().getLineCount()-1)>=t.getText().length());}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)check(((ViewGroup)v).getChildAt(i));}
 @Test public void hourlyAiCanArriveAfterTheNormalCardWithoutRestartingPresentation()throws Exception{WeatherForecast.Summary w=new WeatherForecast.Summary("28°C","Nublado","9 km/h","70%","Modelo horário",now+600000,false,"28°C","30°C","70%","9 km/h","15 km/h","Cloudy",now-60000,now-120000);WeatherCardView card=new WeatherCardView(c,null,w,false,false);assertFalse(texts(card).contains("RESUMO COM IA"));c.getSharedPreferences("weather-ai",0).edit().putString("hourly",payload("hourly",w.generatedAt,w.referenceAt,"Na Liberdade, a previsão horária é de 28 °C. O modelo horário indica céu nublado.")).commit();card.refreshBriefing();assertTrue(texts(card).contains("RESUMO COM IA"));export(card,"HOURLY");}
 @Test public void rainAiRemainsCompactAndCannotAppearOnFictitiousDemonstrations()throws Exception{RainForecast.Summary r=new RainForecast.Summary("soon","fraca","Chuva prevista",0,2,"",now-60000,now+600000,false,15,40,25,3,"Duração estimada: ~25 min");c.getSharedPreferences("weather-ai",0).edit().putString("rain",payload("rain",r.at,0,"O início da chuva está previsto próximo de 14:20 BRT. A intensidade prevista no início é moderada, de 3 mm/h.")).commit();RainStripView card=new RainStripView(c,r,false,false);assertTrue(texts(card).contains("IA ·"));export(card,"RAIN");assertFalse(texts(new RainStripView(c,r,true,false)).contains("IA ·"));}
}
